    if (p) { if (!V.hudUp) V.hudUp = t; V.hudGone = 0; } else if (V.hudUp) { V.hudGone = t; V.hudWasUp = t - V.hudUp; V.hudUp = 0; if (V.hudWasUp > 600) hides.push(t); }
